insert into public.questions (subject, skill_tag, difficulty, format, purpose, stem_i18n, choices, answer, explanation_i18n, status) values
('math', 'arithmetic-fractions', 1, 'mc', 'placement', '{"en": "What is 3/4 + 1/8?", "ko": "3/4 + 1/8 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "7/8"}}, {"id": "b", "text_i18n": {"en": "4/12"}}, {"id": "c", "text_i18n": {"en": "1/2"}}, {"id": "d", "text_i18n": {"en": "5/8"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Convert 3/4 to 6/8, then 6/8 + 1/8 = 7/8.", "ko": "3/4를 6/8로 통분하면 6/8 + 1/8 = 7/8 입니다."}'::jsonb, 'published'),
('math', 'arithmetic-decimals', 1, 'mc', 'placement', '{"en": "What is 0.6 × 0.3?", "ko": "0.6 × 0.3 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "1.8"}}, {"id": "b", "text_i18n": {"en": "0.18"}}, {"id": "c", "text_i18n": {"en": "0.018"}}, {"id": "d", "text_i18n": {"en": "18"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "6 × 3 = 18, and there are two decimal places total, so 0.18.", "ko": "6 × 3 = 18이고 소수점 아래 자리수가 총 2개이므로 0.18입니다."}'::jsonb, 'published'),
('math', 'arithmetic-negatives', 1, 'mc', 'placement', '{"en": "What is −7 + 12?", "ko": "−7 + 12 는 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "−19"}}, {"id": "b", "text_i18n": {"en": "19"}}, {"id": "c", "text_i18n": {"en": "5"}}, {"id": "d", "text_i18n": {"en": "−5"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "12 − 7 = 5. The larger absolute value (12) is positive.", "ko": "12 − 7 = 5. 절댓값이 큰 12가 양수이므로 답도 양수입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-percent', 2, 'mc', 'placement', '{"en": "What is 15% of 80?", "ko": "80의 15%는 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "12"}}, {"id": "b", "text_i18n": {"en": "15"}}, {"id": "c", "text_i18n": {"en": "8"}}, {"id": "d", "text_i18n": {"en": "20"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "0.15 × 80 = 12.", "ko": "0.15 × 80 = 12 입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-ratio', 2, 'mc', 'placement', '{"en": "A recipe uses 2 cups of flour for every 3 cups of milk. How much flour is needed for 9 cups of milk?", "ko": "우유 3컵마다 밀가루 2컵을 쓰는 레시피가 있습니다. 우유 9컵에는 밀가루 몇 컵이 필요한가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "4 cups"}}, {"id": "b", "text_i18n": {"en": "6 cups"}}, {"id": "c", "text_i18n": {"en": "9 cups"}}, {"id": "d", "text_i18n": {"en": "13.5 cups"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "9 ÷ 3 = 3 groups, 2 × 3 = 6 cups of flour.", "ko": "우유 9컵은 3배이므로 밀가루도 2 × 3 = 6컵입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-exponents', 2, 'mc', 'placement', '{"en": "What is 2³ × 2²?", "ko": "2³ × 2² 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "2⁵ = 32"}}, {"id": "b", "text_i18n": {"en": "2⁶ = 64"}}, {"id": "c", "text_i18n": {"en": "4⁵ = 1024"}}, {"id": "d", "text_i18n": {"en": "2 = 2"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Same base: add exponents. 3 + 2 = 5, so 2⁵ = 32.", "ko": "밑이 같으면 지수를 더합니다. 3 + 2 = 5이므로 2⁵ = 32입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-order-of-operations', 2, 'mc', 'placement', '{"en": "What is 4 + 3 × (6 − 4)²?", "ko": "4 + 3 × (6 − 4)² 은 얼마인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "16"}}, {"id": "b", "text_i18n": {"en": "28"}}, {"id": "c", "text_i18n": {"en": "10"}}, {"id": "d", "text_i18n": {"en": "196"}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "(6−4)² = 4, then 3 × 4 = 12, then 4 + 12 = 16.", "ko": "(6−4)² = 4, 3 × 4 = 12, 4 + 12 = 16 순서로 계산합니다."}'::jsonb, 'published'),
('math', 'algebra-one-step-equations', 3, 'mc', 'placement', '{"en": "Solve for x: 3x − 5 = 16", "ko": "x를 구하세요: 3x − 5 = 16"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "x = 3"}}, {"id": "b", "text_i18n": {"en": "x = 7"}}, {"id": "c", "text_i18n": {"en": "x = 11/3"}}, {"id": "d", "text_i18n": {"en": "x = 21"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "3x = 21, so x = 7.", "ko": "3x = 21 이므로 x = 7 입니다."}'::jsonb, 'published'),
('math', 'algebra-linear-graphs', 3, 'mc', 'placement', '{"en": "What is the slope of the line through (1, 2) and (3, 8)?", "ko": "점 (1, 2)와 (3, 8)을 지나는 직선의 기울기는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "6"}}, {"id": "b", "text_i18n": {"en": "1/3"}}, {"id": "c", "text_i18n": {"en": "3"}}, {"id": "d", "text_i18n": {"en": "2"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "slope = (8−2)/(3−1) = 6/2 = 3.", "ko": "기울기 = (8−2)/(3−1) = 6/2 = 3 입니다."}'::jsonb, 'published'),
('math', 'geometry-area', 2, 'mc', 'placement', '{"en": "A rectangle is 8 cm long and 5 cm wide. What is its area?", "ko": "가로 8cm, 세로 5cm 직사각형의 넓이는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "13 cm²"}}, {"id": "b", "text_i18n": {"en": "26 cm²"}}, {"id": "c", "text_i18n": {"en": "40 cm²"}}, {"id": "d", "text_i18n": {"en": "80 cm²"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Area = length × width = 8 × 5 = 40 cm².", "ko": "넓이 = 가로 × 세로 = 8 × 5 = 40 cm² 입니다."}'::jsonb, 'published'),
('math', 'data-mean', 2, 'mc', 'placement', '{"en": "What is the mean of 4, 7, 9, and 12?", "ko": "4, 7, 9, 12의 평균은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "7"}}, {"id": "b", "text_i18n": {"en": "8"}}, {"id": "c", "text_i18n": {"en": "9"}}, {"id": "d", "text_i18n": {"en": "32"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "(4+7+9+12)/4 = 32/4 = 8.", "ko": "(4+7+9+12)/4 = 32/4 = 8 입니다."}'::jsonb, 'published'),
('math', 'algebra-systems', 4, 'mc', 'placement', '{"en": "If x + y = 10 and x − y = 4, what is x?", "ko": "x + y = 10 이고 x − y = 4 일 때, x는?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "3"}}, {"id": "b", "text_i18n": {"en": "6"}}, {"id": "c", "text_i18n": {"en": "7"}}, {"id": "d", "text_i18n": {"en": "10"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Add the equations: 2x = 14, so x = 7.", "ko": "두 식을 더하면 2x = 14, x = 7 입니다."}'::jsonb, 'published'),
('rla', 'grammar-nouns', 1, 'mc', 'placement', '{"en": "Choose the correct plural: ''There are three ___ in the yard.''", "ko": "올바른 복수형을 고르세요: ''There are three ___ in the yard.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "child"}}, {"id": "b", "text_i18n": {"en": "childs"}}, {"id": "c", "text_i18n": {"en": "children"}}, {"id": "d", "text_i18n": {"en": "childrens"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "''Child'' has an irregular plural: ''children''.", "ko": "''child''의 복수형은 불규칙형인 ''children''입니다."}'::jsonb, 'published'),
('rla', 'grammar-verb-agreement', 2, 'mc', 'placement', '{"en": "Choose the correct verb: ''Each of the students ___ a laptop.''", "ko": "올바른 동사를 고르세요: ''Each of the students ___ a laptop.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "have"}}, {"id": "b", "text_i18n": {"en": "has"}}, {"id": "c", "text_i18n": {"en": "are having"}}, {"id": "d", "text_i18n": {"en": "were having"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "''Each'' is singular, so use ''has''.", "ko": "''Each''는 단수 취급하므로 ''has''를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-pronouns', 2, 'mc', 'placement', '{"en": "Choose the correct pronoun: ''My brother and ___ went to the market.''", "ko": "올바른 대명사를 고르세요: ''My brother and ___ went to the market.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "me"}}, {"id": "b", "text_i18n": {"en": "I"}}, {"id": "c", "text_i18n": {"en": "myself"}}, {"id": "d", "text_i18n": {"en": "mine"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "Subject position needs the subject pronoun ''I''.", "ko": "주어 자리에는 주격 대명사 ''I''를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-punctuation', 2, 'mc', 'placement', '{"en": "Which sentence is punctuated correctly?", "ko": "구두점이 올바른 문장을 고르세요."}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Its raining, we stayed inside."}}, {"id": "b", "text_i18n": {"en": "It''s raining, so we stayed inside."}}, {"id": "c", "text_i18n": {"en": "Its'' raining so we stayed inside."}}, {"id": "d", "text_i18n": {"en": "It''s raining so, we stayed inside."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "''It''s'' = ''it is''; a comma goes before the conjunction ''so'' joining two clauses.", "ko": "''It''s''는 ''it is''의 축약형이고, 두 절을 잇는 접속사 ''so'' 앞에 쉼표를 씁니다."}'::jsonb, 'published'),
('rla', 'grammar-sentence-structure', 3, 'mc', 'placement', '{"en": "Which of the following is a complete sentence?", "ko": "완전한 문장을 고르세요."}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Because the rain stopped."}}, {"id": "b", "text_i18n": {"en": "Running through the park."}}, {"id": "c", "text_i18n": {"en": "The library opens at nine."}}, {"id": "d", "text_i18n": {"en": "After we finished dinner and washed the dishes."}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "It has a subject (the library) and a main verb (opens); the others are fragments.", "ko": "주어(the library)와 본동사(opens)가 있는 완전한 문장입니다. 나머지는 조각문입니다."}'::jsonb, 'published'),
('rla', 'reading-main-idea', 3, 'mc', 'placement', '{"en": "\"Bees are vital to farming. As they collect nectar, they carry pollen between flowers, which lets crops produce fruit. Without bees, many foods we eat every day would disappear.\" — What is the main idea?", "ko": "\"Bees are vital to farming...\" 지문의 중심 생각은 무엇인가요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "Bees make honey that people enjoy."}}, {"id": "b", "text_i18n": {"en": "Bees are essential for growing the food we eat."}}, {"id": "c", "text_i18n": {"en": "Flowers need water to produce fruit."}}, {"id": "d", "text_i18n": {"en": "Farming is difficult without machines."}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "The passage focuses on bees'' role in food production through pollination.", "ko": "지문은 수분(pollination)을 통해 벌이 식량 생산에 필수적이라는 내용입니다."}'::jsonb, 'published'),
('rla', 'reading-inference', 3, 'mc', 'placement', '{"en": "\"Maria checked her watch again and tapped her foot as the bus finally appeared around the corner.\" — What can you infer about Maria?", "ko": "\"Maria checked her watch again...\" 에서 Maria에 대해 추론할 수 있는 것은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "She is waiting impatiently."}}, {"id": "b", "text_i18n": {"en": "She missed the bus."}}, {"id": "c", "text_i18n": {"en": "She dislikes buses."}}, {"id": "d", "text_i18n": {"en": "Her watch is broken."}}]'::jsonb, '{"choice": "a"}'::jsonb, '{"en": "Checking the watch repeatedly and tapping her foot are signs of impatience.", "ko": "시계를 반복해서 보고 발을 구르는 행동은 초조함의 표시입니다."}'::jsonb, 'published'),
('rla', 'reading-detail', 2, 'mc', 'placement', '{"en": "\"The market opens at 6 a.m. on weekdays but at 8 a.m. on weekends.\" — When does the market open on Saturday?", "ko": "\"The market opens at 6 a.m. on weekdays but at 8 a.m. on weekends.\" — 토요일에는 몇 시에 여나요?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "6 a.m."}}, {"id": "b", "text_i18n": {"en": "7 a.m."}}, {"id": "c", "text_i18n": {"en": "8 a.m."}}, {"id": "d", "text_i18n": {"en": "It is closed."}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "Saturday is a weekend, so it opens at 8 a.m.", "ko": "토요일은 주말이므로 오전 8시에 엽니다."}'::jsonb, 'published'),
('rla', 'grammar-modifiers', 3, 'mc', 'placement', '{"en": "Choose the correct word: ''She sings very ___.''", "ko": "올바른 단어를 고르세요: ''She sings very ___.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "good"}}, {"id": "b", "text_i18n": {"en": "well"}}, {"id": "c", "text_i18n": {"en": "goodly"}}, {"id": "d", "text_i18n": {"en": "best"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "An adverb (''well'') modifies the verb ''sings''.", "ko": "동사 ''sings''를 꾸미는 것은 부사 ''well''입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-arith-prop', 1, 'mc', 'practice', '{"en": "Which number is a factor of 24?", "ko": "24의 약수인 것은?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "5"}}, {"id": "b", "text_i18n": {"en": "7"}}, {"id": "c", "text_i18n": {"en": "8"}}, {"id": "d", "text_i18n": {"en": "9"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "24 ÷ 8 = 3 with no remainder, so 8 is a factor.", "ko": "24 ÷ 8 = 3으로 나누어떨어지므로 8은 24의 약수입니다."}'::jsonb, 'published'),
('math', 'pre-algebra-arith-prop', 2, 'mc', 'practice', '{"en": "What is the prime factorization of 36?", "ko": "36을 소인수분해하면?"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "2 × 18"}}, {"id": "b", "text_i18n": {"en": "2² × 3²"}}, {"id": "c", "text_i18n": {"en": "4 × 9"}}, {"id": "d", "text_i18n": {"en": "6²"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "36 = 4 × 9 = 2² × 3². Only primes appear in a prime factorization.", "ko": "36 = 4 × 9 = 2² × 3². 소인수분해에는 소수만 나타나야 합니다."}'::jsonb, 'published'),
('rla', 'grammar-nouns', 1, 'mc', 'practice', '{"en": "Which word in this sentence is a noun? ''The teacher quickly closed the door.''", "ko": "다음 문장에서 명사인 것은? ''The teacher quickly closed the door.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "quickly"}}, {"id": "b", "text_i18n": {"en": "closed"}}, {"id": "c", "text_i18n": {"en": "teacher"}}, {"id": "d", "text_i18n": {"en": "the"}}]'::jsonb, '{"choice": "c"}'::jsonb, '{"en": "''Teacher'' names a person, so it is a noun (''door'' is also a noun).", "ko": "''teacher''는 사람을 가리키는 명사입니다 (''door''도 명사)."}'::jsonb, 'published'),
('rla', 'grammar-nouns', 2, 'mc', 'practice', '{"en": "Choose the correct possessive: ''The ___ toys are everywhere.''", "ko": "올바른 소유격을 고르세요: ''The ___ toys are everywhere.''"}'::jsonb, '[{"id": "a", "text_i18n": {"en": "childrens"}}, {"id": "b", "text_i18n": {"en": "children''s"}}, {"id": "c", "text_i18n": {"en": "childrens''"}}, {"id": "d", "text_i18n": {"en": "children"}}]'::jsonb, '{"choice": "b"}'::jsonb, '{"en": "''Children'' is already plural; add apostrophe + s: children''s.", "ko": "''children''은 이미 복수형이므로 아포스트로피 + s를 붙여 children''s가 됩니다."}'::jsonb, 'published');